Here's a complete React TypeScript example with a functional component:

```tsx
import React, { useState } from 'react';

// Define a type for user data
interface User {
  id: number;
  name: string;
  email: string;
  age: number;
}

// Define a type for component props
interface UserProfileProps {
  users: User[];
  onUserClick: (user: User) => void;
}

// Functional component with TypeScript
const UserProfile: React.FC<UserProfileProps> = ({ users, onUserClick }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Filter users based on search term
  const filteredUsers = users.filter(user => 
    user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="user-profile">
      <h2>User Directory</h2>

      {/* Search input */}
      <div className="search-container">
        <input
          type="text"
          placeholder="Search users..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-input"
        />
      </div>

      {/* Users list */}
      <div className="users-list">
        {filteredUsers.length > 0 ? (
          filteredUsers.map(user => (
            <div
              key={user.id}
              className="user-card"
              onClick={() => onUserClick(user)}
            >
              <h3>{user.name}</h3>
              <p>Email: {user.email}</p>
              <p>Age: {user.age} years</p>
            </div>
          ))
        ) : (
          <p>No users found matching your search.</p>
        )}
      </div>
    </div>
  );
};

// Example usage
const App: React.FC = () => {
  const initialUsers: User[] = [
    { id: 1, name: 'John Doe', email: 'john@example.com', age: 28 },
    { id: 2, name: 'Jane Smith', email: 'jane@example.com', age: 32 },
    { id: 3, name: 'Bob Johnson', email: 'bob@example.com', age: 25 },
    { id: 4, name: 'Alice Brown', email: 'alice@example.com', age: 30 }
  ];

  const handleUserClick = (user: User) => {
    console.log('User clicked:', user);
    // You can add more complex interaction logic here
  };

  return (
    <div className="app">
      <UserProfile 
        users={initialUsers} 
        onUserClick={handleUserClick} 
      />
    </div>
  );
};

export default App;
```

## Key TypeScript features used:

1. **Interfaces**: `User` and `UserProfileProps` define the shape of data
2. **Type annotations**: Parameters and return values have explicit types
3. **Generic components**: `React.FC` with proper component type
4. **Type safety**: TypeScript ensures props have the correct types
5. **Proper typing**: Variables and functions are properly typed

## To run this example:

1. Create a new React project with TypeScript:
```bash
npx create-react-app my-app --template typescript
cd my-app
```

2. Replace the contents of `src/App.tsx` with the code above

3. Start the development server:
```bash
npm start
```

This example demonstrates how TypeScript helps catch errors at compile time and improves code readability and maintainability.

